export const COLORS = { 1: "#00e5ff", 2: "#ff2e88" };

export function connect(onPacket) {
  let busy = false;
  let pending = null;

  async function handle(buf) {
    busy = true;
    const view = new DataView(buf);
    const len = view.getUint32(0, true);
    const state = JSON.parse(new TextDecoder().decode(new Uint8Array(buf, 4, len)));
    let bitmap = null;
    if (buf.byteLength > 4 + len) {
      // Bild und Zustand gehören zusammen; erst nach dem Dekodieren gemeinsam zeichnen.
      bitmap = await createImageBitmap(new Blob([new Uint8Array(buf, 4 + len)], { type: "image/jpeg" }));
    }
    onPacket(state, bitmap);
    busy = false;
    if (pending) {
      const next = pending;
      pending = null;
      handle(next);
    }
  }

  function open() {
    const ws = new WebSocket(`ws://${location.host}/ws`);
    ws.binaryType = "arraybuffer";
    ws.onmessage = (e) => {
      // Rückstau verwerfen: nur das neueste Bild zählt.
      if (busy) pending = e.data;
      else handle(e.data);
    };
    ws.onclose = () => setTimeout(open, 1000);
  }
  open();
}

export async function act(name, data = {}) {
  const res = await fetch(`/api/${name}`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(data),
  });
  return res.json();
}

// Letterbox: Kamerabild passt ins Canvas, Seitenverhältnis bleibt. Ein Rand (`pad`) gehört zum Bild,
// die Koordinaten bleiben aber Arena-Einheiten mit (0, 0) in der Feldecke.
export function fit(canvas, frame) {
  const p = frame.pad || 0;
  const s = Math.min(canvas.width / (frame.w + 2 * p), canvas.height / (frame.h + 2 * p));
  return { s, ox: (canvas.width - frame.w * s) / 2, oy: (canvas.height - frame.h * s) / 2 };
}

export function drawFrame(ctx, v, frame, bitmap) {
  const p = frame.pad || 0;
  const [x, y] = toCanvas(v, [-p, -p]);
  ctx.drawImage(bitmap, x, y, (frame.w + 2 * p) * v.s, (frame.h + 2 * p) * v.s);
}

export function toCanvas(v, p) {
  return [v.ox + p[0] * v.s, v.oy + p[1] * v.s];
}

export function toFrame(v, x, y) {
  return [(x - v.ox) / v.s, (y - v.oy) / v.s];
}

export function pathPoly(ctx, v, pts) {
  ctx.beginPath();
  pts.forEach((p, i) => {
    const [x, y] = toCanvas(v, p);
    if (i === 0) ctx.moveTo(x, y);
    else ctx.lineTo(x, y);
  });
  ctx.closePath();
}

export function resizeCanvas(canvas) {
  const r = canvas.getBoundingClientRect();
  const dpr = window.devicePixelRatio || 1;
  const w = Math.round(r.width * dpr);
  const h = Math.round(r.height * dpr);
  if (canvas.width !== w || canvas.height !== h) {
    canvas.width = w;
    canvas.height = h;
  }
}

// Tastenkürzel in beiden Fenstern gleich, damit die Bühne im Vollbild auch bedienbar bleibt.
export function hotkeys(getNames = () => []) {
  window.addEventListener("keydown", (e) => {
    if (e.target instanceof HTMLInputElement) {
      if (e.key === "Enter") act("start", { names: getNames() });
      return;
    }
    const map = {
      o: ["spawn", { kind: "obstacle" }],
      p: ["spawn", { kind: "powerup" }],
      k: ["shrink"],
      n: ["new_battle"],
      s: ["start", { names: getNames() }],
      1: ["ulti", { player: 1 }],
      2: ["ulti", { player: 2 }],
    };
    const hit = map[e.key] || map[e.key.toLowerCase()];
    if (!hit) return;
    e.preventDefault();
    act(hit[0], hit[1] || {});
  });
}
